'use client'

import { useEffect, useMemo, useRef, useState } from 'react'
import { ExternalLink } from 'lucide-react'
import type { Lang } from '@/lib/data'
import { UI } from '@/lib/assistant'
import { CATEGORY_BY_ID, type GroupId, type Place } from '@/lib/nearby-data'

const HL: Record<Lang, string> = { mr: 'mr', hi: 'hi', en: 'en' }

const GROUP_COLORS: Record<GroupId, string> = {
  health: '#10b981',
  education: '#6366f1',
  government: '#0ea5e9',
  agriculture: '#22c55e',
  transport: '#f59e0b',
  emergency: '#ef4444',
  daily: '#8b5cf6',
}

function project(lat: number, lng: number, zoom: number): { x: number; y: number } {
  const size = 256 * Math.pow(2, zoom)
  const sin = Math.sin((lat * Math.PI) / 180)
  const x = ((lng + 180) / 360) * size
  const y = (0.5 - Math.log((1 + sin) / (1 - sin)) / (4 * Math.PI)) * size
  return { x, y }
}

/**
 * Real Google Map (embed, no API key) with Google-style service pins overlaid
 * using the standard Web-Mercator projection so they sit exactly on their
 * coordinates. The map underneath is Google's real renderer, so the POI layer
 * (hospitals, schools, etc.) is shown in full detail.
 */
export function NearbyMap({
  center,
  places,
  lang,
  zoom = 14,
  onSelect,
  selectedId,
  className = '',
}: {
  center: { lat: number; lng: number }
  places: Place[]
  lang: Lang
  zoom?: number
  onSelect?: (p: Place) => void
  selectedId?: string | null
  className?: string
}) {
  const wrapRef = useRef<HTMLDivElement>(null)
  const [size, setSize] = useState<{ w: number; h: number } | null>(null)
  const [mounted, setMounted] = useState(false)

  useEffect(() => setMounted(true), [])
  useEffect(() => {
    const el = wrapRef.current
    if (!el) return
    const ro = new ResizeObserver((entries) => {
      const r = entries[0]?.contentRect
      if (r) setSize({ w: r.width, h: r.height })
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  const selected = selectedId ? places.find((p) => p.id === selectedId) ?? null : null

  const src = useMemo(() => {
    const focus = selected ?? null
    const q = focus ? `${focus.lat},${focus.lng}` : `${center.lat},${center.lng}`
    const z = focus ? 16 : zoom
    return `https://www.google.com/maps?q=${q}&z=${z}&hl=${HL[lang]}&output=embed`
  }, [center.lat, center.lng, selected, zoom, lang])

  const c = project(center.lat, center.lng, selected ? 16 : zoom)
  const markers = (size && mounted ? places : []).map((p) => {
    const pt = project(p.lat, p.lng, selected ? 16 : zoom)
    return { p, px: pt.x - c.x + size!.w / 2, py: pt.y - c.y + size!.h / 2 }
  })

  return (
    <div
      ref={wrapRef}
      className={`relative w-full overflow-hidden rounded-3xl shadow-md ring-1 ring-border/60 ${className}`}
      style={{ height: 320 }}
    >
      {mounted && (
        <iframe
          key={selectedId ?? 'center'}
          title="Map"
          src={src}
          className="absolute inset-0 h-full w-full border-0"
          allowFullScreen
          loading="lazy"
          referrerPolicy="no-referrer-when-downgrade"
        />
      )}

      <div className="pointer-events-none absolute inset-0">
        {/* Current location */}
        <div
          className="absolute"
          style={{
            left: size ? size.w / 2 : 0,
            top: size ? size.h / 2 : 0,
            transform: 'translate(-50%, -50%)',
          }}
        >
          <span className="relative flex size-7 items-center justify-center">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-sky-400 opacity-60" />
            <span className="relative inline-flex size-4 rounded-full border-2 border-white bg-sky-600 shadow" />
          </span>
        </div>

        {/* Service pins */}
        {markers.map(({ p, px, py }) => {
          const cat = CATEGORY_BY_ID[p.type]
          const color = GROUP_COLORS[p.group]
          const sel = selectedId === p.id
          return (
            <button
              key={p.id}
              type="button"
              onClick={() => onSelect?.(p)}
              className={`pointer-events-auto absolute flex flex-col items-center transition-transform ${sel ? 'z-20 scale-110' : 'z-10'}`}
              style={{ left: px, top: py, transform: 'translate(-50%, -100%)' }}
              aria-label={p.name.en}
            >
              <span
                className="flex h-8 w-8 items-center justify-center rounded-full text-base shadow-md ring-2 ring-white"
                style={{ background: color }}
              >
                {cat?.emoji ?? '📍'}
              </span>
              <span className="h-2.5 w-2.5 -mt-1 rotate-45 rounded-br-sm" style={{ background: color }} />
              {sel && (
                <span className="mt-0.5 max-w-36 truncate rounded-full bg-black/75 px-2 py-0.5 text-xs font-bold text-white">
                  {p.name[lang]}
                </span>
              )}
            </button>
          )
        })}
      </div>

      {/* Open in Google Maps */}
      <a
        href={`https://www.google.com/maps/search/?api=1&query=${selected ? `${selected.lat},${selected.lng}` : `${center.lat},${center.lng}`}`}
        target="_blank"
        rel="noreferrer"
        className="absolute bottom-3 right-3 flex items-center gap-1.5 rounded-lg bg-[#1a73e8] px-3.5 py-2 text-xs font-bold text-white shadow-lg ring-1 ring-black/10 active:scale-95"
      >
        <ExternalLink className="size-3.5" />
        {UI.openInMaps[lang]}
      </a>
    </div>
  )
}
