export const DISTRICTS: District[] = RAW_DISTRICTS.map((d) => ({
  id: d.id,
  name: d.name,
  stateId: d.stateId,
  lat: d.lat,
  lng: d.lng,
}))

export const TALUKAS: Taluka[] = RAW_DISTRICTS.flatMap((d) =>
  d.talukas.map((t) => ({ id: t.id, name: t.name, districtId: d.id, lat: t.lat, lng: t.lng })),
)

export const VILLAGES: Village[] = RAW_DISTRICTS.flatMap((d) =>
  d.talukas.flatMap((t) =>
    t.villages.map((v) => ({
      id: v.id,
      name: v.name,
      talukaId: t.id,
      districtId: d.id,
      stateId: d.stateId,
      lat: v.lat,
      lng: v.lng,
    })),
  ),
)

export const stateById = (id: string) => STATES.find((s) => s.id === id) ?? null
export const districtById = (id: string) => DISTRICTS.find((d) => d.id === id) ?? null
export const talukaById = (id: string) => TALUKAS.find((t) => t.id === id) ?? null
export const villageById = (id: string) => VILLAGES.find((v) => v.id === id) ?? null

export const districtsOfState = (stateId: string) => DISTRICTS.filter((d) => d.stateId === stateId)
export const talukasOfDistrict = (districtId: string) => TALUKAS.filter((t) => t.districtId === districtId)
export const villagesOfTaluka = (talukaId: string) => VILLAGES.filter((v) => v.talukaId === talukaId)

/* ===================== Deterministic place generator ===================== */

function hashId(s: string): number {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return Math.abs(h)
}

function fakePhone(seed: string): string {
  const h = hashId(seed)
  const digits = (h % 100000000).toString().padStart(8, '0')
  return `9${(h % 9) + 1}${digits}`
}

/** Deterministic geo offset: village services ~0.2-1km, taluka services ~1.2-2.8km. */
function placeOffset(seed: string, level: 'village' | 'taluka', lat: number): { lat: number; lng: number } {
  const h = hashId(seed)
  const angle = ((h % 628) / 100) * Math.PI
  const distM = level === 'village' ? 200 + (h % 800) : 1200 + ((h >> 3) % 1600)
  const latM = Math.cos(angle) * distM
  const lngM = Math.sin(angle) * distM
  return { lat: latM / 111320, lng: lngM / (111320 * Math.cos((lat * Math.PI) / 180)) }
}

function catRating(seed: string, catId: CategoryId): number | null {
  if (catId === 'water' || catId === 'toilet' || catId === 'atm') return null
  const h = hashId(seed)
  return Math.round((3.4 + (h % 150) / 100) * 10) / 10
}

const ORD: Record<'mr' | 'hi' | 'en', string[]> = { mr: ['', '२ '], hi: ['', '२ '], en: ['', '2nd '] }

/** Localized place name, e.g. "प्राथमिक शाळा, वाघोली" or "सरकारी रुग्णालय, बारामती". */
function placeName(cat: Category, village: Village, taluka: Taluka | null, i: number): LangText {
  const loc = cat.level === 'taluka' && taluka ? taluka.name : village.name
  const o = ORD['mr']
  const h = ORD['hi']
  const e = ORD['en']
  return {
    mr: `${o[i]}${cat.labels.mr}, ${loc.mr}`,
    hi: `${h[i]}${cat.labels.hi}, ${loc.hi}`,
    en: `${e[i]}${cat.labels.en}, ${loc.en}`,
  }
}

/** Deterministic mock places around a village (a small offline bundle of the whole state). */
export function getVillagePlaces(villageId: string): Place[] {
  const village = villageById(villageId)
  if (!village) return []
  const taluka = talukaById(village.talukaId)
  const places: Place[] = []
  for (const cat of CATEGORIES) {
    for (let i = 0; i < cat.count; i++) {
      const seed = `${village.id}-${cat.id}-${i}`
      const off = placeOffset(seed, cat.level, village.lat)
      places.push({
        id: seed,
        name: placeName(cat, village, taluka, i),
        type: cat.id,
        group: cat.group,
        lat: village.lat + off.lat,
        lng: village.lng + off.lng,
        phone: fakePhone(seed),
        hours: cat.hours,
        rating: catRating(seed, cat.id),
      })
    }
  }
  return places
}

export function haversineKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180
  const R = 6371
  const dLat = toRad(lat2 - lat1)
  const dLng = toRad(lng2 - lng1)
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2
  return 2 * R * Math.asin(Math.sqrt(a))
}

export type OpenStatus = 'open' | 'closed'

export function openStatus(place: Place, now: Date): OpenStatus {
  const h = place.hours
  if (!h) return 'open'
  const cur = now.getHours() * 60 + now.getMinutes()
  const [oh, om] = h.open.split(':').map(Number)
  const [ch, cm] = h.close.split(':').map(Number)
  const openMin = oh * 60 + om
  const closeMin = ch * 60 + cm
  if (openMin <= closeMin) return cur >= openMin && cur < closeMin ? 'open' : 'closed'
  return cur >= openMin || cur < closeMin ? 'open' : 'closed'
}

export function formatDistance(km: number, lang: 'mr' | 'hi' | 'en'): string {
  const value = km < 10 ? km.toFixed(1) : Math.round(km).toString()
  const unit = lang === 'en' ? 'km' : 'किमी'
  return `${value} ${unit}`
}

/** Nearest village to a GPS coordinate, or null if too far away. */
export function nearestVillage(lat: number, lng: number): Village | null {
  let best: Village | null = null
  let bestKm = Number.POSITIVE_INFINITY
  for (const v of VILLAGES) {
    const km = haversineKm(lat, lng, v.lat, v.lng)
    if (km < bestKm) {
      bestKm = km
      best = v
    }
  }
  return best && bestKm <= 100 ? best : null
}

/** Find the nearest district centre to a GPS coordinate. */
export function nearestDistrictId(lat: number, lng: number): string | null {
  let best: string | null = null
  let bestKm = Number.POSITIVE_INFINITY
  for (const d of DISTRICTS) {
    const km = haversineKm(lat, lng, d.lat, d.lng)
    if (km < bestKm) {
      bestKm = km
      best = d.id
    }
  }
  return best && bestKm <= 200 ? best : null
}
